INSERT INTO "strategy_changes" VALUES(1,'2026-09-26T15:38:48Z','dt-1.0.0','dt-2.0.0','151a53cc9d61857388483bbd9dd40667ce916de8692ec18db95fe58222f21411','5be50a36474207f73ac64ff3040af551624d04fffc00fa76e60adbab325400b7','2026-09-28','Day trader v2: only trade stocks in play that just reported earnings (Nasdaq calendar), and put the stop at the low of the first 5-minute bar instead of 0.10 x ATR. v1 lost all 10 live trades to stops hit by normal noise.','Pre-registered 4-variant test (research/PREREGISTRATION.md, research/dt_variants.json): 46 sessions 5-min data -15.5% -> +11.8% (halves -12.9%/-3.0% -> +9.5%/+2.1%); 20 sessions 1-min data -6.7% -> +2.4% (13 trades, 46% won). SPY +2.9% / +0.4%. Small, overlapping samples.');
INSERT INTO "strategy_changes" VALUES(2,'2026-09-28T22:03:00Z','dt-2.0.0','dt-3.0.0','5be50a36474207f73ac64ff3040af551624d04fffc00fa76e60adbab325400b7','617c95587c1a67d7855d82c915a23cecae2940cad86837a4fe0a51d1c1bb913c','next decision after 2026-09-28 deployment','Day trader v3: retain earnings-catalyst opening-range rules, size to 0.25% risk per trade including costs within a 1% session stop-loss budget. Tighten drawdown pause/halt to 5%/10%. Tested trailing-stop proposal rejected.','research/revamp_2026_09_28/SUMMARY.md: 62 tests passed; independent review; fixed-variant replay at 1m/5m. Drawdown improved but returns lower; no claim of proven profit.');
